DO $$
DECLARE
  v_course_id bigint;
BEGIN
  -- Get the Code 8 course id
  SELECT id INTO v_course_id FROM courses WHERE code = 'code8';

  IF v_course_id IS NULL THEN
    RAISE EXCEPTION 'Course with code=code8 not found. Did you run schema.sql first?';
  END IF;

  -- Clear existing test 1 questions for this course (safe to re-run)
  DELETE FROM quiz_questions WHERE course_id = v_course_id AND test_number = 1;

  -- Insert all 62 questions

  RAISE NOTICE 'Inserted % questions for course_id=%', 62, v_course_id;
END $$;